def strategy(history, rng):
    if not history:
        return 'C'
    n = len(history)
    if n < 2:
        return 'C'
    last_me, last_opp = history[-1]
    if n < 10:
        if last_opp == 'D':
            return 'D'
        return 'C'
    coop = sum(1 for a, b in history if b == 'C')
    defco = n - coop
    if defco == 0:
        return 'C'
    if coop == 0:
        return 'D'
    if n >= 20:
        recent = history[-10:]
        rcoop = sum(1 for a, b in recent if b == 'C')
        if rcoop >= 9:
            return 'C'
        if rcoop <= 1:
            return 'D'
    if last_opp == 'D':
        if n >= 4:
            prev_me, prev_opp = history[-2]
            if prev_opp == 'D' and prev_me == 'C':
                return 'D'
        return 'D'
    else:
        if n >= 6:
            last6 = history[-6:]
            dcount = sum(1 for a, b in last6 if b == 'D')
            if dcount >= 3:
                return 'D'
        return 'C'

